styles.content:
.wf-case-form {
  color: var(--wf-color-text, #172033);
  font-family: var(--wf-font-body, inherit);
}

.wf-case-form__form {
  display: grid;
  gap: 1rem;
  max-width: 40rem;
}

.wf-case-form__title {
  margin: 0;
  font-size: 1.35rem;
  font-weight: var(--wf-heading-weight, 700);
  letter-spacing: -0.02em;
}

.wf-case-form__lead,
.wf-case-form__hint,
.wf-case-form__status {
  margin: 0;
  color: var(--wf-color-muted, #526071);
  line-height: 1.5;
}

.wf-case-form__group {
  margin: 0;
  padding: 0;
  border: 0;
  display: grid;
  gap: 0.75rem;
}

.wf-case-form__legend {
  padding: 0;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--wf-color-muted, #526071);
}

.wf-case-form__grid {
  display: grid;
  gap: 0.85rem;
}

.wf-case-form__grid[data-columns="2"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.wf-case-form__field {
  display: grid;
  align-content: start;
  gap: 0.35rem;
  min-width: 0;
}

.wf-case-form__label {
  font-size: 0.92rem;
  font-weight: 650;
}

.wf-case-form__control {
  width: 100%;
  box-sizing: border-box;
  border: 1px solid var(--wf-color-border, #ccd6e2);
  border-radius: var(--wf-radius, 0.6rem);
  background: var(--wf-color-background, #fff);
  color: inherit;
  font: inherit;
  padding: 0.65rem 0.75rem;
}

.wf-case-form__control:focus {
  border-color: var(--wf-color-primary, #0f766e);
  outline: 2px solid color-mix(in srgb, var(--wf-color-primary, #0f766e) 18%, transparent);
}

.wf-case-form__check {
  width: 1rem;
  height: 1rem;
  margin-right: 0.45rem;
  accent-color: var(--wf-color-primary, #0f766e);
}

.wf-case-form__combo { position: relative; min-width: 0; }
.wf-case-form__combo > select[hidden] { display: none; }
.wf-case-form__combo-input { padding-right: 2.75rem; }
.wf-case-form__combo-toggle {
  position: absolute; inset: 1px 0.5rem 1px auto; width: 2rem;
  display: grid; place-items: center; padding: 0; border: 0;
  background: transparent; color: var(--wf-color-muted, #526071); cursor: pointer;
}
.wf-case-form__combo-toggle::after {
  content: ''; width: 0.4rem; height: 0.4rem;
  border-right: 2px solid currentColor; border-bottom: 2px solid currentColor;
  transform: translateY(-2px) rotate(45deg);
}
.wf-case-form__combo-popup {
  position: absolute; z-index: 30; top: calc(100% + 4px); left: 0; right: 0;
  border: 1px solid var(--wf-color-border, #ccd6e2);
  border-radius: var(--wf-radius, 0.6rem);
  background: var(--wf-color-surface, var(--wf-color-background, #fff));
  overflow: hidden;
}
.wf-case-form__combo-popup[hidden] { display: none; }
.wf-case-form__combo[data-open-up="true"] .wf-case-form__combo-popup { top: auto; bottom: calc(100% + 4px); }
.wf-case-form__combo-list { max-height: min(15rem, 40vh); overflow-y: auto; overscroll-behavior: contain; }
.wf-case-form__combo-option { padding: 0.65rem 0.75rem; cursor: pointer; overflow-wrap: anywhere; }
.wf-case-form__combo-option:hover,
.wf-case-form__combo-option[aria-selected="true"] {
  background: color-mix(in srgb, var(--wf-color-primary, #0f766e) 14%, var(--wf-color-surface, var(--wf-color-background, #fff)));
}
.wf-case-form__combo-count { margin: 0; padding: 0.5rem 0.75rem; font-size: 0.8rem; color: var(--wf-color-muted, #526071); border-top: 1px solid var(--wf-color-border, #ccd6e2); }
.wf-case-form__protection { min-width: 0; }
.wf-case-form__protection-status { margin: 0; color: var(--wf-color-muted, #526071); font-size: 0.85rem; }
.wf-case-form__protection-retry {
  margin-top: 0.5rem; padding: 0.5rem 0.75rem; border-radius: var(--wf-radius, 0.6rem);
  border: 1px solid var(--wf-color-border, #ccd6e2); background: var(--wf-color-surface, var(--wf-color-background, #fff));
  color: inherit; font: inherit; cursor: pointer;
}
.wf-case-form__submit:disabled { opacity: 0.6; cursor: default; }

.wf-case-form__error {
  margin: 0;
  min-height: 1em;
  color: var(--wf-color-danger, #9f1239);
  font-size: 0.82rem;
}

.wf-case-form__error:empty {
  display: none;
}

.wf-case-form__submit {
  display: inline-flex;
  align-items: center;
  text-decoration: none;
  justify-self: start;
  min-height: 42px;
  border: 0;
  border-radius: var(--wf-radius, 0.6rem);
  background: var(--wf-color-primary, #0f766e);
  color: #fff;
  font: inherit;
  font-weight: var(--wf-heading-weight, 700);
  padding: 0.65rem 1rem;
  cursor: pointer;
}

.wf-case-form__submit:focus-visible {
  outline: 2px solid var(--wf-color-primary, #0f766e);
  outline-offset: 2px;
}

.wf-case-form [data-wf-case-source] {
  display: none;
}

@media (max-width: 720px) {
  .wf-case-form__grid[data-columns="2"] {
    grid-template-columns: 1fr;
  }
}

/* Conditional fields and standard phone widget inherit the public site's tokens. */
.wf-case-form__field[hidden], .wf-case-form__group[hidden] { display: none; }
.wf-case-form .iti {
  width: 100%; min-width: 0;
  --iti-border-color: var(--wf-color-border, #ccd6e2);
  --iti-country-selector-bg: var(--wf-color-surface, var(--wf-color-background, #fff));
  --iti-icon-color: var(--wf-color-muted, #526071);
  --iti-hover-color: color-mix(in srgb, var(--wf-color-primary, #0f766e) 12%, transparent);
}
.wf-case-form .iti__country-selector { color: var(--wf-color-text, #172033); }
.wf-case-form .iti__search-input { background: var(--wf-color-background, #fff); color: inherit; }

