(function () {
  var SRC = '/common/Elastyc/CaseForm/case-form.js?v=20261014-profile';
  function attr(node, name) { return node.getAttribute(name) || ''; }
  function readList(host, selector, map) {
    var out = [];
    Array.prototype.forEach.call(host.querySelectorAll(selector), function (node) { out.push(map(node)); });
    return out;
  }
  function binding(host) {
    return {
      formKey: attr(host, 'data-form-key'),
      title: attr(host, 'data-title'),
      lead: attr(host, 'data-lead'),
      columns: attr(host, 'data-columns'),
      submitLabel: attr(host, 'data-submit'),
      successMessage: attr(host, 'data-success'),
      groups: readList(host, '[data-wf-case-groups] li', function (node) {
        return { key: attr(node, 'data-key'), label: attr(node, 'data-label') };
      }),
      fields: readList(host, '[data-wf-case-fields] li', function (node) {
        return {
          key: attr(node, 'data-key'),
          label: attr(node, 'data-label'),
          inheritedLabel: attr(node, 'data-inherited-label'),
          hint: attr(node, 'data-hint'),
          type: attr(node, 'data-type'),
          required: attr(node, 'data-required'),
          format: attr(node, 'data-format'),
          phoneCountry: attr(node, 'data-phone-country'),
          'connected-field': attr(node, 'data-connected-field'),
          'connected-values': attr(node, 'data-connected-values'),
          rules: JSON.parse(attr(node, 'data-rules') || '[]'),
          group: attr(node, 'data-group'),
          options: attr(node, 'data-options')
        };
      })
    };
  }
  function boot() {
    if (!window.ElastycCaseForm) return;
    Array.prototype.forEach.call(document.querySelectorAll('[data-wf-case-form]'), function (host) {
      var mount = host.querySelector('[data-wf-case-mount]');
      if (!mount || mount.getAttribute('data-wf-case-ready') === 'true') return;
      mount.setAttribute('data-wf-case-ready', 'true');
      var wrap = host.closest('[data-wf-instance]');
      var requested = wrap && attr(wrap, 'data-wf-case-mode') === 'live' ? 'live' : 'mock';
      var framed = false;
      try { framed = window.parent !== window; } catch (error) { framed = true; }
      var mode = framed ? 'mock' : requested;
      var channel = wrap && attr(wrap, 'data-wf-channel') === 'candidate' ? 'candidate' : 'production';
      window.ElastycCaseForm.init({
        host: mount,
        binding: binding(host),
        mode: mode,
        submit: {
          instanceKey: wrap ? attr(wrap, 'data-wf-instance') : '',
          schemaHash: wrap ? attr(wrap, 'data-wf-case-schema') : '',
          csrfCookie: 'wf_case_csrf',
          identityContext: wrap ? attr(wrap, 'data-wf-case-identity') : '',
          route: wrap ? attr(wrap, 'data-wf-case-route') : '',
          channel: channel,
          protection: {
            provider: wrap ? attr(wrap, 'data-wf-case-protection') : '',
            siteKey: wrap ? attr(wrap, 'data-wf-case-site-key') : ''
          }
        }
      });
    });
  }
  if (window.ElastycCaseForm) { boot(); return; }
  if (window.__wfCaseFormBoot) { window.__wfCaseFormBoot.push(boot); return; }
  window.__wfCaseFormBoot = [boot];
  var script = document.createElement('script');
  script.src = SRC;
  if (document.currentScript && document.currentScript.nonce) script.nonce = document.currentScript.nonce;
  script.onload = function () {
    (window.__wfCaseFormBoot || []).splice(0).forEach(function (fn) { fn(); });
  };
  script.onerror = function () {
    Array.prototype.forEach.call(document.querySelectorAll('[data-wf-case-mount]'), function (mount) {
      if (!mount.textContent) mount.textContent = 'Forma trenutno nije dostupna.';
    });
  };
  document.head.appendChild(script);
})();
